    round(SUM (i.amount_after * 1),2) AS sales

FROM dmp_order_item i
LEFT JOIN dmp_order_info o ON i.order_id = o.id



            AND o.platform_create_time >= #{params.startTime}


            AND o.platform_create_time < #{params.endTime}





            AND o.delivery_time >= #{params.startTime}


            AND o.delivery_time < #{params.endTime}




        AND o.dept_id IN

            #{deptId}




        AND o.source_platform IN

            #{platform}




        AND o.site IN

            #{site}




        AND o.shop_name IN

            #{shopName}




        AND i.sku_no IN

            #{sku}




        AND i.sku_no IN
        ( SELECT sku_no FROM product_detail pd INNER JOIN product_info pi ON pi.id=pd.product_id WHERE
        pi.category_id IN

            #{category}

        )



        AND i.sku_no IN
        ( SELECT sku_no FROM product_detail pd INNER JOIN product_info pi ON pi.id=pd.product_id WHERE
        pi.brand_name IN

            #{brand}

        )



        AND o.charge_id IN

            #{userId}




        ${params.permissionSql}


GROUP BY flag

SELECT
SUM ( i.quantity ) AS salesQty,
COUNT(DISTINCT ( o.platform_order_id )) AS orderCount,

    round(SUM (i.amount_after * i.${settleRate}),2) AS sales,


    round(SUM (i.amount_after * 1),2) AS sales,

i.sku_no AS skuNo,
min(i.item_name) AS productName
