LEFT JOIN dmp_order_info o ON i.order_id = o.ID



            o.platform_create_time >= #{params.startTime}


            AND o.platform_create_time < #{params.endTime}





            AND o.delivery_time >= #{params.startTime}


            AND o.delivery_time < #{params.endTime}




        AND o.dept_id IN

            #{deptId}




        AND o.source_platform IN

            #{platform}




        AND o.site IN

            #{site}




        AND o.shop_name IN

            #{shopName}




        AND i.sku_no IN

            #{sku}




        AND i.sku_no IN
        ( SELECT sku_no FROM product_detail pd INNER JOIN product_info pi ON pi.id=pd.product_id WHERE
        pi.category_id IN

            #{category}

        )



